17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
33	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
34	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.validation.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.validation.InvalidTelephoneException;
37	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
39	import org.springframework.samples.petclinic.rest.validation.ValidationErrorsResponse;
40	import org.springframework.security.access.AccessDeniedException;
41	import org.springframework.validation.BindingResult;
42	import org.springframework.web.bind.MethodArgumentNotValidException;
43	import org.springframework.web.bind.annotation.ControllerAdvice;
44	import org.springframework.web.bind.annotation.ExceptionHandler;
45	import org.springframework.web.bind.annotation.ResponseBody;
46	
47	/**
48	 * Global Exception handler for REST controllers.
49	 * <p>
50	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
51	 *
52	 * @author Vitaliy Fedoriv
53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	
63	    private final OwnerFieldsValidator ownerFieldsValidator;
64	
65	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
66	        this.ownerFieldsValidator = ownerFieldsValidator;
67	    }
68	
69	    /**
70	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
71	     * class.
72	     *
73	     * @param e     Object referring to the thrown exception.
74	     * @param status HTTP response status.
75	     * @param url URL request.
76	     */
77	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
78	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
79	        problemDetail.setType(URI.create(url.toString()));
80	        problemDetail.setTitle(e.getClass().getSimpleName());
81	        problemDetail.setDetail(detail);
82	        problemDetail.setProperty("timestamp", Instant.now());
83	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
84	        return problemDetail;
85	    }
86	
87	    /**
88	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
89	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
90	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
91	     * would catch it and report an authorization failure as a 500.
92	     *
93	     * @param e The {@link AccessDeniedException} to propagate
94	     * @throws AccessDeniedException always
95	     */
96	    @ExceptionHandler(AccessDeniedException.class)
97	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
98	        throw e;
99	    }
100	
101	    /**
102	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
103	     *
104	     * @param e The {@link Exception} to be handled
105	     * @param request {@link HttpServletRequest} object referring to the current request.
106	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
107	     */
108	    @ExceptionHandler(Exception.class)
109	    @ResponseBody
110	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
111	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
112	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
113	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
114	        return ResponseEntity.status(status).body(detail);
115	    }
116	
117	    /**
118	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
119	     * method returns a 404 Not Found status if an entity does not exist.
120	     *
121	     * @param e The {@link DataIntegrityViolationException} to be handled
122	     * @param request {@link HttpServletRequest} object referring to the current request.
123	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
124	     */
125	    @ExceptionHandler(DataIntegrityViolationException.class)
126	    @ResponseBody
127	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
128	        logger.warn("Data integrity violation at {} {}: {}",
129	            request.getMethod(),
130	            request.getRequestURI(),
131	            e.getMessage());
132	        logger.debug("Data integrity violation stacktrace", e);
133	        HttpStatus status = HttpStatus.NOT_FOUND;
134	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
135	        return ResponseEntity.status(status).body(detail);
136	    }
137	
138	    /**
139	     * Handles exception thrown by Bean Validation on controller methods parameters
140	     *
141	     * @param e The {@link MethodArgumentNotValidException} to be handled
142	     * @param request {@link HttpServletRequest} object referring to the current request.
143	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
144	     */
145	    @ExceptionHandler(MethodArgumentNotValidException.class)
146	    @ResponseBody
147	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
148	        HttpStatus status = HttpStatus.BAD_REQUEST;
149	        BindingErrorsResponse errors = new BindingErrorsResponse();
150	        BindingResult bindingResult = e.getBindingResult();
151	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
152	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
153	            if (!missingFields.isEmpty()) {
154	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
155	            }
156	        }
157	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
158	        if (bindingResult.hasErrors()) {
159	            errors.addAllErrors(bindingResult);
160	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
161	                .map(fieldError -> {
162	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
163	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
164	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
165	                        fieldError.getField(),
166	                        defaultMessage,
167	                        rejectedValue);
168	                    return new ValidationMessageDto(message)
169	                        .putAdditionalProperty("field", fieldError.getField())
170	                        .putAdditionalProperty("rejectedValue", rejectedValue)
171	                        .putAdditionalProperty("defaultMessage", defaultMessage);
172	                })
173	                .toList();
174	            logger.debug("Validation error at {} {}: {}",
175	                request.getMethod(),
176	                request.getRequestURI(),
177	                bindingResult.getFieldErrors());
178	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
179	            return ResponseEntity.status(status).body(detail);
180	        }
181	        return ResponseEntity.status(status).body(detail);
182	    }
183	
184	    /**
185	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created with required
186	     * fields that are missing or blank. Returns a 400 Bad Request whose {@code errors} array lists
187	     * the name of each offending field.
188	     *
189	     * @param e The {@link MissingOwnerFieldsException} to be handled
190	     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
191	     */
192	    @ExceptionHandler(MissingOwnerFieldsException.class)
193	    @ResponseBody
194	    public ResponseEntity<ValidationErrorsResponse> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
195	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new ValidationErrorsResponse(e.getFields()));
196	    }
197	
198	    /**
199	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not
200	     * reduce to exactly ten digits. Returns a 400 Bad Request whose {@code errors} array
201	     * names the offending field.
202	     *
203	     * @param e The {@link InvalidTelephoneException} to be handled
204	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
205	     */
206	    @ExceptionHandler(InvalidTelephoneException.class)
207	    @ResponseBody
208	    public ResponseEntity<ValidationErrorsResponse> handleInvalidTelephoneException(InvalidTelephoneException e) {
209	        logger.debug("Invalid telephone: {}", e.getMessage());
210	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
211	            .body(new ValidationErrorsResponse(List.of(InvalidTelephoneException.FIELD)));
212	    }
213	
214	    /**
215	     * Handles {@link InvalidEmailException} raised when an owner's email is present but is
216	     * not a syntactically valid address. Returns a 400 Bad Request whose {@code errors}
217	     * array names the offending field.
218	     *
219	     * @param e The {@link InvalidEmailException} to be handled
220	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
221	     */
222	    @ExceptionHandler(InvalidEmailException.class)
223	    @ResponseBody
224	    public ResponseEntity<ValidationErrorsResponse> handleInvalidEmailException(InvalidEmailException e) {
225	        logger.debug("Invalid email: {}", e.getMessage());
226	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
227	            .body(new ValidationErrorsResponse(List.of(InvalidEmailException.FIELD)));
228	    }
229	
230	    /**
231	     * Handles {@link DuplicateTelephoneException} raised when an owner is created with a
232	     * normalized telephone that is already used by another owner. Returns a 409 Conflict
233	     * whose {@code errors} array names the offending field.
234	     *
235	     * @param e The {@link DuplicateTelephoneException} to be handled
236	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
237	     */
238	    @ExceptionHandler(DuplicateTelephoneException.class)
239	    @ResponseBody
240	    public ResponseEntity<ValidationErrorsResponse> handleDuplicateTelephoneException(DuplicateTelephoneException e) {
241	        logger.debug("Duplicate telephone: {}", e.getMessage());
242	        return ResponseEntity.status(HttpStatus.CONFLICT)
243	            .body(new ValidationErrorsResponse(List.of(DuplicateTelephoneException.FIELD)));
244	    }
245	
246	}
